    } else {
        parts.join(" + ', ' + ")
    };
    let _ = writeln!(src, "            return '{base}(' + {joined} + ')'");
    src.push_str("        def __setattr__(self, name, value):\n");
    src.push_str("            raise AttributeError(f'cannot assign to field {name!r}')\n");
